// Genereras av kallor-biologi/omrade1/exportsite.py (sajtkonv.py) – ändra inte för hand.
// Biologi område 1: varje moment i tre nivåer (lättläst, grundtext, fördjupning), skrivet för skärm i sajtens vanliga sidformat. Elevversion, utan facit.
var innehall = window.innehall || {};
innehall["biologi-m-1-1-1"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "🌱", "titel": "Vad är biologi?", "text": ["<p>Biologi är läran om allt som lever.</p>", "<p>Allt som lever kallas <strong>organismer</strong>. Djur, växter, svampar och bakterier är organismer.</p>", "<p>Biologer forskar om organismer. De forskar också om människans kropp.</p>", "<p>Det finns många sorters biologer. Här är fyra:</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade1/l_yrken.png\" alt=\"\"></figure>", "<p>Biologer arbetar ute i naturen eller inne i ett labb.</p>", "<p>Många biologer hjälper till att skydda naturen eller att göra nya mediciner.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Biologi är läran om allt som lever. Allt som lever kallas organismer.</div>"]}, {"ikon": "✏️", "titel": "Öva", "text": ["<ol class=\"ovning\"><li><strong>Ringa in.</strong> Vad är en organism?<div class=\"alt\"><span>Allt som lever</span> &nbsp;·&nbsp; <span>En sten</span> &nbsp;·&nbsp; <span>Ett tal</span></div></li><li><strong>Dra streck.</strong> Vad forskar biologerna om? Dra streck.<div class=\"alt\"><span>Botaniker</span> &nbsp;·&nbsp; <span>Marinbiolog</span> &nbsp;·&nbsp; <span>Mikrobiolog</span> &nbsp;·&nbsp; <span>Zoolog</span> &nbsp;·&nbsp; <span>djur</span> &nbsp;·&nbsp; <span>livet i havet</span> &nbsp;·&nbsp; <span>små organismer, som bakterier</span> &nbsp;·&nbsp; <span>växter</span></div></li><li><strong>Fyll i.</strong> Skriv rätt ord på linjen.<div class=\"alt\">Ord att välja: labb · naturen · kropp</div><p>Biologer kan arbeta ute i ________.</p><p>Biologer kan också arbeta inne i ett ________.</p><p>Biologer forskar också om människans ________.</p></li></ol>"]}, {"ikon": "❓", "titel": "Från fråga till plan", "text": ["<p>Forskare börjar med en fråga. Men alla frågor går inte att undersöka.</p>", "<p>En fråga som går att undersöka kallas en <strong>undersökningsbar fråga</strong>. Man kan svara på den genom att <strong>mäta</strong> eller <strong>titta</strong>.</p>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Går inte att undersöka</th><th>Går att undersöka</th></tr><tr><td>Är solrosor fina?</td><td>Hur mycket växer en solros på en vecka?</td></tr><tr><td>Är musik bra när man pluggar?</td><td>Kommer man ihåg fler ord efter att ha lyssnat på musik?</td></tr></table></div>", "<p>Sedan gissar forskaren vad svaret blir. Det kallas en <strong>hypotes</strong>. Man skriver också varför man tror det.</p>", "<p>Forskare arbetar i steg. Stegen går runt i en cirkel.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade1/l_cykel.png\" alt=\"\"></figure>", "<p><span class=\"pahittat\">Påhittat exempel</span> Ella undrar: <em>Växer krasse bättre i ljus eller i mörker?</em></p>", "<p>Hypotes: <em>Krassen blir högst i ljus, eftersom växter behöver ljus.</em></p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade1/l_krasse.png\" alt=\"\"></figure>", "<p>Hon gör ett <strong>rättvist test</strong> med två lådor.</p>", "<p>Ella ändrar bara en sak: ljuset. Allt annat är lika. Det man ändrar kallas en <strong>variabel</strong>.</p>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Ella ändrar</th><th>Ella mäter</th><th>Ella håller lika</th></tr><tr><td>ljuset (ljus eller mörker)</td><td>hur hög krassen blir (mm)</td><td>jord, vatten, antal frön</td></tr></table></div>"]}, {"ikon": "🧪", "titel": "Säkert i labbet", "text": ["<p>Läs hela instruktionen först. Ha skyddsglasögon när läraren säger det. Ät och drick aldrig i labbet. Fråga om du är osäker.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>En fråga som går att undersöka kan man mäta. I ett rättvist test ändrar man bara en sak.</div>"]}, {"ikon": "✏️", "titel": "Öva", "text": ["<ol class=\"ovning\"><li><strong>Ringa in.</strong> Vilken fråga går att undersöka?<div class=\"alt\"><span>Är hundar snälla?</span> &nbsp;·&nbsp; <span>Hur långt hoppar en groda?</span> &nbsp;·&nbsp; <span>Är sommar bäst?</span></div></li><li><strong>Dra streck.</strong> Dra streck till rätt förklaring.<div class=\"alt\"><span>Det Ella mäter</span> &nbsp;·&nbsp; <span>Det Ella ändrar</span> &nbsp;·&nbsp; <span>Det som är lika</span> &nbsp;·&nbsp; <span>hur hög krassen blir</span> &nbsp;·&nbsp; <span>jord och vatten</span> &nbsp;·&nbsp; <span>ljuset</span></div></li><li><strong>Kryssa.</strong> Vad ska vara lika i båda lådorna? Kryssa i rätt rutor.<div class=\"alt\"><span>Lika mycket vatten</span> &nbsp;·&nbsp; <span>Lika många frön</span> &nbsp;·&nbsp; <span>Samma jord</span> &nbsp;·&nbsp; <span>Samma ljus</span></div></li><li><strong>Kryssa.</strong> Vad gör du i labbet? Kryssa i rätt rutor.<div class=\"alt\"><span>Frågar om jag är osäker</span> &nbsp;·&nbsp; <span>Läser hela instruktionen först</span> &nbsp;·&nbsp; <span>Springer runt</span> &nbsp;·&nbsp; <span>Äter godis</span></div></li><li><strong>Skriv.</strong> Varför ska man bara ändra en sak i ett test?</li></ol>"]}]}, "vanlig": {"sektioner": [{"ikon": "🌱", "titel": "Vad är biologi?", "text": ["<p>Biologi betyder ”läran om livet”. Ordet kommer från grekiskans <em>bios</em> (liv) och <em>logos</em> (lära). Biologi handlar om allt som lever: bakterier, svampar, växter, djur och människor. Allt levande kallas <strong>organismer</strong>. Biologer undersöker hur organismer är uppbyggda, hur de fungerar, hur de samspelar med varandra och hur livet har utvecklats.</p>", "<p>Biologi är en av <strong>naturvetenskaperna</strong>, tillsammans med bland annat kemi och fysik. Gemensamt för dem är att de försöker förklara naturen med hjälp av <strong>systematiska undersökningar</strong>: undersökningar som görs noggrant och planerat, så att andra kan kontrollera och upprepa dem.</p>"]}, {"ikon": "🌱", "titel": "Biologer arbetar på många sätt", "text": ["<p>Livet är så stort att ingen kan vara expert på allt. Därför specialiserar sig biologer. Vissa arbetar ute i naturen, andra i laboratorier, på sjukhus eller vid en dator där de analyserar stora mängder data.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade1/l_yrken.png\" alt=\"Bild 1.1 Fyra sorters biologer: zoolog (djur), botaniker (växter), mikrobiolog (små organismer) och marinbiolog (livet i havet).\"><figcaption><strong>Bild 1.1</strong> Fyra sorters biologer: zoolog (djur), botaniker (växter), mikrobiolog (små organismer) och marinbiolog (livet i havet).</figcaption></figure>"], "fragor": ["Vad betyder ordet biologi?", "Vad menas med att en undersökning är systematisk?", "Välj två av biologerna i bild 1.1. Ge ett exempel på en fråga som var och en kan undersöka."]}, {"ikon": "❓", "titel": "Från fråga till plan", "text": ["<p>All forskning börjar med nyfikenhet. Men en bra undersökning börjar med en <strong>undersökningsbar fråga</strong>: en fråga som går att besvara med mätningar eller observationer. ”Är solrosor fina?” är en åsikt. ”Hur mycket växer en solros på en vecka?” går att mäta.</p>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Går inte att undersöka</th><th>Går att undersöka</th><th>Varför är den bättre?</th></tr><tr><td>Är musik bra när man pluggar?</td><td>Kommer man ihåg fler ord efter att ha lyssnat på musik än efter tystnad?</td><td>Den säger vad som ska mätas (antal ord) och vad som ska jämföras.</td></tr><tr><td>Är krasse bra?</td><td>Växer krasse högre i ljus än i mörker?</td><td>Man kan mäta höjden i millimeter.</td></tr></table></div>"]}, {"ikon": "📖", "titel": "Forskning är en cykel", "text": ["<p>Arbetet följer ofta stegen i bild 1.2. Efter frågan formulerar forskaren en <strong>hypotes</strong>: ett möjligt svar på frågan som går att pröva, med en motivering. Därefter planeras och görs en undersökning, och resultatet leder till en slutsats och ofta till en ny fråga. Svaret ska bygga på <strong>belägg</strong>, alltså mätningar och observationer, och inte på vad någon tycker.</p>", "<p>En <strong>teori</strong> är något större än en hypotes: en förklaring som har prövats av många forskare under lång tid och som stämmer med väldigt många observationer. Evolutionsteorin och cellteorin är exempel.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade1/l_cykel.png\" alt=\"Bild 1.2 Den vetenskapliga arbetsgången. I verkligheten hoppar forskare ofta fram och tillbaka mellan stegen.\"><figcaption><strong>Bild 1.2</strong> Den vetenskapliga arbetsgången. I verkligheten hoppar forskare ofta fram och tillbaka mellan stegen.</figcaption></figure>"]}, {"ikon": "🔎", "titel": "Ett rättvist försök", "text": ["<p><span class=\"pahittat\">Påhittat exempel</span> Klass 7B undrar om krasse behöver ljus för att växa. Hypotesen är: <em>Krassen i ljus växer högre, eftersom växter behöver ljus för fotosyntesen.</em> En <strong>variabel</strong> är något som kan ändras eller mätas. För att testet ska bli rättvist får bara <em>en</em> variabel ändras åt gången. Allt annat måste vara lika, annars vet man inte vad som orsakade resultatet.</p>", "<p>Ofta har man också en <strong>kontrollgrupp</strong>, där man inte ändrar något, så att man har något att jämföra med. I krassförsöket är krassen i ljus kontrollgrupp.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade1/v_krasse.png\" alt=\"Bild 1.3 Krasse som vuxit i sju dagar i ljus (A) och i en mörk låda (B).\"><figcaption><strong>Bild 1.3</strong> Krasse som vuxit i sju dagar i ljus (A) och i en mörk låda (B).</figcaption></figure>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Typ av variabel</th><th>Vad betyder det?</th><th>I krassförsöket</th></tr><tr><td>Oberoende variabel</td><td>Det du själv ändrar med flit.</td><td>Ljus eller mörker</td></tr><tr><td>Beroende variabel</td><td>Det du mäter – det som kanske påverkas.</td><td>Krassens höjd i mm</td></tr><tr><td>Kontrollerade variabler</td><td>Allt annat, som måste vara lika i båda försöken.</td><td>Jord, vatten, temperatur, antal frön, tid</td></tr></table></div>"]}, {"ikon": "🧪", "titel": "Säkerhet i labbet", "text": ["<ol><li>Läs hela instruktionen innan du börjar.</li><li>Använd skyddsglasögon och förkläde när läraren säger det. Sätt upp långt hår.</li><li>Ät, drick eller smaka aldrig något i labbet.</li><li>Säg till direkt om något går sönder eller om du skadar dig.</li><li>Städa och tvätta händerna när du är klar.</li></ol>", "<div class=\"ruta ruta-varning\"><span class=\"ruta-rubrik\">Faroetiketter</span>Kemikalier som kan vara farliga har en varningssymbol på förpackningen. Läs alltid etiketten innan du använder något.</div>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>Varför ska man aldrig äta i labbet, även när man bara använder ofarliga saker just den dagen?</div>"], "fragor": ["Gör frågan ”Är hundar snälla?” om till en undersökningsbar fråga.", "Vad är skillnaden mellan oberoende och beroende variabel?", "Varför behövs en kontrollgrupp?", "Varför får man bara ändra en variabel åt gången?"]}], "begrepp": [{"term": "Biologi", "forklaring": "Läran om livet och levande organismer."}, {"term": "Hypotes", "forklaring": "Ett möjligt, prövbart svar med en motivering."}, {"term": "Kontrollgrupp", "forklaring": "Grupp där man inte ändrar något, att jämföra med."}, {"term": "Naturvetenskap", "forklaring": "Vetenskaper som undersöker naturen, t.ex. biologi, kemi och fysik."}, {"term": "Organism", "forklaring": "En levande varelse, till exempel en bakterie, en svamp, en växt eller ett djur."}, {"term": "Undersökningsbar fråga", "forklaring": "En fråga som kan besvaras med mätningar eller observationer."}, {"term": "Variabel", "forklaring": "Något som kan ändras eller mätas i en undersökning."}]}, "fordjupning": {"sektioner": [{"ikon": "🌱", "titel": "Vad är biologi?", "text": ["<p>Föreställ dig att ett företag påstår att deras nya tablett gör att förkylningar går över snabbare. Hur skulle man testa det? Det låter enkelt: ge tabletten till några förkylda personer och se om de blir friska. Men de flesta förkylningar går över av sig själva inom en vecka. Hur vet man då att det var tabletten som hjälpte? En bra plan svarar på det i förväg.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade1/f_rct.png\" alt=\"Bild F1.1 En randomiserad, dubbelblind och placebokontrollerad studie: en av de mest pålitliga sorternas medicinska försök.\"><figcaption><strong>Bild F1.1</strong> En randomiserad, dubbelblind och placebokontrollerad studie: en av de mest pålitliga sorternas medicinska försök.</figcaption></figure>"]}, {"ikon": "📖", "titel": "Så motiverar du valen i din plan", "text": ["<p><strong>Variabler.</strong> Välj en oberoende variabel och motivera varför just den. Välj en beroende variabel som verkligen mäter det du vill veta (giltighet). Lista vad som måste hållas lika.</p>", "<p><strong>Kontrollgrupp och placebo.</strong> Kontrollgruppen får inte behandlingen. Får den en likadan tablett utan verksamt ämne, kan förväntningar inte förklara skillnaden.</p>", "<p><strong>Randomisering.</strong> Slumpen bestämmer vem som hamnar i vilken grupp. Annars kan forskaren omedvetet lägga de friskaste i den ena gruppen.</p>", "<p><strong>Blindning.</strong> Om varken deltagare eller forskare vet vem som fått vad är studien dubbelblind. Då blir det svårare att påverka resultatet, även omedvetet.</p>", "<p><strong>Antal upprepningar.</strong> Med fem personer i varje grupp kan slumpen avgöra resultatet. Med hundratals blir slumpens betydelse liten. I ett skolförsök kan du inte ha hundratals, så du måste vara öppen med vad det betyder för hur säker slutsatsen blir.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Resonera om störningar</span>Du ska testa om du minns fler ord med musik. Vad kan störa? Hur kan du planera så att varje störning minskar?</div>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Del av planen</th><th>Fråga att svara på</th><th>Motivera</th></tr><tr><td>Frågeställning</td><td>Går den att besvara med mätning?</td><td>Skriv vad som ska mätas.</td></tr><tr><td>Variabler</td><td>Vad ändras, mäts och hålls lika?</td><td>Varför just dessa?</td></tr><tr><td>Mätmetod</td><td>Hur mäter jag, med vilken noggrannhet?</td><td>Varför är metoden giltig?</td></tr><tr><td>Upprepning</td><td>Hur många försök och deltagare?</td><td>Hur påverkar antalet slumpen?</td></tr><tr><td>Störningar</td><td>Vad kan göra resultatet fel?</td><td>Hur förebygger jag det?</td></tr></table></div>"]}], "begrepp": [{"term": "Dubbelblind", "forklaring": "Varken deltagare eller forskare vet vem som fått vad."}, {"term": "Randomisering", "forklaring": "Slumpmässig fördelning till grupper."}, {"term": "Stickprov", "forklaring": "De individer man undersöker, som ska representera en större grupp."}]}}, nivaStandard: "vanlig"};
innehall["biologi-m-1-1-2"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📊", "titel": "Dokumentera", "text": ["<p>När du mäter ska du skriva ner värdena direkt. Använd en <strong>tabell</strong>.</p>", "<p>Tabellen ska ha rubriker. Skriv också enhet, till exempel mm eller s.</p>", "<p><span class=\"pahittat\">Påhittade siffror</span> Så här kan Ellas tabell se ut:</p>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Dag</th><th>Ljus (mm)</th><th>Mörker (mm)</th></tr><tr><td>1</td><td>5</td><td>5</td></tr><tr><td>3</td><td>15</td><td>25</td></tr><tr><td>5</td><td>28</td><td>42</td></tr><tr><td>7</td><td>40</td><td>60</td></tr></table></div>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade1/l_stapel.png\" alt=\"\"></figure>", "<p>Ett <strong>diagram</strong> gör siffrorna lätta att jämföra. Ella ritar ett stapeldiagram.</p>", "<p>Ett bra diagram har <strong>rubrik</strong>. Axlarna har namn och enhet. Staplarna har namn.</p>"]}, {"ikon": "📊", "titel": "Så skriver du en rapport", "text": ["<ol><li><strong>Fråga.</strong> Vad ville vi ta reda på?</li><li><strong>Så gjorde vi.</strong> Vad ändrade vi? Vad mätte vi? Vad höll vi lika?</li><li><strong>Resultat.</strong> Tabell och diagram.</li><li><strong>Slutsats.</strong> Svara på frågan. Skriv vad som kan ha blivit fel.</li></ol>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Skriv värdena i en tabell med rubriker och enheter. Rita ett diagram med rubrik och axlar.</div>"]}, {"ikon": "✏️", "titel": "Öva", "text": ["<ol class=\"ovning\"><li><strong>Ringa in.</strong> Vad ska stå i tabellens rubrik?<div class=\"alt\"><span>Höjd (mm)</span> &nbsp;·&nbsp; <span>Bara en siffra</span> &nbsp;·&nbsp; <span>Inget</span></div></li><li><strong>Rita och skriv.</strong> Rita ett stapeldiagram: Grupp A 12 cm, Grupp B 8 cm. Skriv rubrik och namn på axlarna.</li><li><strong>Skriv siffror.</strong> Sätt delarna av rapporten i rätt ordning. Skriv 1, 2, 3 och 4.<div class=\"alt\"><span>Slutsats</span> &nbsp;·&nbsp; <span>Fråga</span> &nbsp;·&nbsp; <span>Resultat</span> &nbsp;·&nbsp; <span>Så gjorde vi</span></div></li><li><strong>Fyll i.</strong> Skriv rätt ord på linjen.<div class=\"alt\">Ord att välja: tabell · rubrik · enhet</div><p>Man skriver värdena i en ________.</p><p>Ett diagram ska ha en ________.</p><p>Efter siffran skriver man en ________, till exempel mm.</p></li></ol>"]}]}, "vanlig": {"sektioner": [{"ikon": "📊", "titel": "Dokumentera", "text": ["<p>Under försöket mäter klassen krassen varje dag och skriver direkt ner värdena i en <strong>tabell</strong>. Tabellen ska ha rubriker, och efter varje mått ska enheten stå, till exempel mm eller s. När försöket är klart räknar man ut <strong>medelvärdet</strong> för varje grupp: lägg ihop alla värden och dela med antalet värden.</p>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Dag</th><th>1</th><th>3</th><th>5</th><th>7</th></tr><tr><td>A · ljus (mm)</td><td>5</td><td>15</td><td>28</td><td>40</td></tr><tr><td>B · mörker (mm)</td><td>5</td><td>25</td><td>42</td><td>60</td></tr></table></div>", "<p class=\"not\"><strong>Tabell 1.1</strong> <span class=\"pahittat\">Påhittade värden</span> Krassens medelhöjd i klassens försök.</p>"]}, {"ikon": "📊", "titel": "Välj diagram", "text": ["<p>Ett diagram gör det lättare att se mönster. Ett <strong>stapeldiagram</strong> passar när du jämför grupper, till exempel höjden efter sju dagar. Ett <strong>linjediagram</strong> passar när något förändras över tid. Tiden sätts på x-axeln och det du mäter på y-axeln. Glöm inte rubrik, namn och enheter på axlarna.</p>", "<p>Läs av diagrammet noga: vilken stapel är högst, hur stor är skillnaden, och vad står siffrorna för?</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade1/l_stapel.png\" alt=\"Bild 1.4 Krassens höjd efter 7 dagar.\"><figcaption><strong>Bild 1.4</strong> Krassens höjd efter 7 dagar.</figcaption></figure>"]}, {"ikon": "📊", "titel": "Skriva en rapport", "text": ["<p>När du har gjort en undersökning redovisar du den i en rapport. Den ska vara så tydlig att någon annan kan göra om försöket och kontrollera ditt resultat.</p>", "<div class=\"kort-rad\"><div class=\"kort\"><strong>Syfte och frågeställning</strong>Vad vill du ta reda på?</div><div class=\"kort\"><strong>Hypotes</strong>Vad tror du och varför?</div><div class=\"kort\"><strong>Material och metod</strong>Vad använde du och hur gjorde du?</div><div class=\"kort\"><strong>Resultat</strong>Vad hände? Tabeller och diagram.</div><div class=\"kort\"><strong>Diskussion och slutsats</strong>Vad betyder resultatet? Felkällor?</div></div>", "<div class=\"ruta ruta-fakta\"><span class=\"ruta-rubrik\">Digitala verktyg</span>Ett kalkylprogram räknar ut medelvärden och ritar diagram åt dig. Mobilkameran kan dokumentera försöket med bilder. Du måste ändå själv avgöra om diagrammet visar det du vill veta.</div>"], "fragor": ["Vad ska en tabell innehålla?", "När passar ett stapeldiagram och när ett linjediagram?", "Räkna ut medelvärdet av 12, 14 och 13 mm.", "Vilka delar ingår i en rapport?"]}]}, "fordjupning": {"sektioner": [{"ikon": "📊", "titel": "Dokumentera", "text": ["<p>Ett diagram visar inte bara svaret. Det visar också hur osäkert svaret är. <span class=\"pahittat\">Påhittat exempel</span> En grupp undersökte hur temperaturen påverkar gasbildningen hos jäst. De gjorde tre försök vid varje temperatur och mätte hur mycket en ballong växte.</p>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Temperatur</th><th>Försök 1</th><th>Försök 2</th><th>Försök 3</th><th>Medelvärde</th></tr><tr><td>10 °C</td><td>13 cm</td><td>12 cm</td><td>14 cm</td><td>13 cm</td></tr><tr><td>25 °C</td><td>22 cm</td><td>24 cm</td><td>23 cm</td><td>23 cm</td></tr><tr><td>40 °C</td><td>31 cm</td><td>18 cm</td><td>30 cm</td><td>?</td></tr></table></div>"]}, {"ikon": "📖", "titel": "Det avvikande värdet", "text": ["<p>Vid 40 °C avviker ett värde mycket från de andra (18 cm). Om man räknar med det blir medelvärdet 26 cm. Utan det blir det 30,5 cm. Vad ska man göra? Man ska inte stryka ett värde bara för att det passar illa. Man frågar först: Finns det en rimlig förklaring, till exempel att ballongen satt löst? Om ja, redovisa värdet, förklara varför det kan vara fel och visa resultatet med och utan det. Om nej, gör fler försök.</p>"]}, {"ikon": "✅", "titel": "Osäkerhet", "text": ["<p>Ju mer mätvärdena skiljer sig inom en grupp, desto osäkrare är medelvärdet. Man kan redovisa osäkerheten genom att visa lägsta och högsta värde. Skillnaden mellan 10 och 25 °C är stor jämfört med spridningen. Skillnaden mellan 25 och 40 °C är mindre tydlig, eftersom ett av värdena avviker.</p>", "<div class=\"ruta ruta-fakta\"><span class=\"ruta-rubrik\">Digitala verktyg</span>I ett kalkylblad kan du räkna medelvärde med och utan ett värde, och rita diagram med både medelvärden och enskilda mätpunkter.</div>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Fundera</span>Vilken slutsats kan du dra om temperaturens påverkan, och vilken kan du inte dra? Vad skulle du göra för att bli säkrare?</div>"]}], "begrepp": [{"term": "Avvikande värde", "forklaring": "Ett värde som ligger långt från de andra."}, {"term": "Osäkerhet", "forklaring": "Hur säkert ett resultat är."}, {"term": "Spridning", "forklaring": "Hur mycket mätvärdena skiljer sig åt."}]}}, nivaStandard: "vanlig"};
innehall["biologi-m-1-1-3"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "✅", "titel": "Värdera", "text": ["<p>Ett resultat kan bli fel. Det beror på <strong>felkällor</strong>.</p>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Felkälla</th><th>Exempel</th></tr><tr><td>Slump</td><td>Man läser av linjalen lite olika varje gång.</td></tr><tr><td>Misstag</td><td>Man mäter från fel ställe på linjalen.</td></tr><tr><td>Olika villkor</td><td>Den ena krassen får mer vatten.</td></tr></table></div>", "<p><strong>Slump</strong> är sådant som bara händer. Därför gör man om testet flera gånger. Då blir resultatet säkrare.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade1/l_stapel.png\" alt=\"\"></figure>", "<p>Slutsatsen ska stämma med resultatet.</p>", "<p><strong>Ellas slutsats:</strong> Krassen blir högre i mörker. Den växer på höjden för att leta efter ljus. Men den mår bäst i ljus.</p>", "<p>Hypotesen var alltså fel. Det gör inget! Man lär sig ändå.</p>", "<p>Ella testade bara krasse. Hon kan inte säga att alla växter gör så. Skriv alltid vad du inte vet.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Resultatet kan bli fel. Gör om testet flera gånger. Slutsatsen ska stämma med resultatet.</div>"]}, {"ikon": "✏️", "titel": "Öva", "text": ["<ol class=\"ovning\"><li><strong>Ringa in.</strong> En fläkt blåser på en av krassarna. Vad är det?<div class=\"alt\"><span>En felkälla</span> &nbsp;·&nbsp; <span>En slutsats</span> &nbsp;·&nbsp; <span>En hypotes</span></div></li><li><strong>Sant eller falskt.</strong> Kryssa i rätt ruta.<div class=\"alt\"><span>Sant</span> &nbsp;·&nbsp; <span>Falskt</span></div></li><li><strong>Fyll i.</strong> Skriv rätt ord på linjen.<div class=\"alt\">Ord att välja: slutsatsen · felkälla · flera</div><p>Något som kan ge fel resultat kallas en ________.</p><p>Man gör testet ________ gånger.</p><p>________ ska stämma med resultatet.</p></li><li><strong>Skriv.</strong> Varför är det bra att göra ett test flera gånger?</li></ol>"]}]}, "vanlig": {"sektioner": [{"ikon": "✅", "titel": "Värdera resultat", "text": ["<p>En forskare frågar sig alltid: Kan jag lita på resultatet? Mätte vi rätt sak? Ett resultat kan bli fel på flera sätt. Sådant som kan ha påverkat resultatet utan att vi ville det kallas <strong>felkällor</strong>.</p>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Typ av felkälla</th><th>Exempel i krassförsöket</th><th>Vad hjälper?</th></tr><tr><td>Slump</td><td>En krasse får av en slump dålig jord. Någon läser av linjalen lite olika varje gång.</td><td>Fler mätningar och upprepning. Slumpen jämnar då ut sig.</td></tr><tr><td>Systematiskt fel</td><td>Mörka lådan blir varmare, så temperaturen och inte ljuset påverkar. Eller man mäter alltid från fel ställe.</td><td>Bättre planering: håll alla andra variabler lika. Kontrollera mätmetoden.</td></tr></table></div>", "<p>Man gör därför försöket flera gånger och räknar ut ett medelvärde. Då får slumpen mindre betydelse. Ett enda avvikande värde bör man undersöka: var det ett misstag, eller säger det något?</p>"]}, {"ikon": "📖", "titel": "Tillförlitlighet och giltighet", "text": ["<p><strong>Tillförlitlighet</strong> handlar om hur säkra mätningarna är: skulle vi få samma resultat om vi gjorde om försöket? <strong>Giltighet</strong> handlar om huruvida vi har mätt det vi ville veta. Är höjden ett bra mått på om krassen ”växer bra”? Det hade kanske varit bättre att väga krassen eller titta på färgen.</p>"]}, {"ikon": "✅", "titel": "Slutsatsen", "text": ["<p>Slutsatsen ska svara på frågan och stämma med resultatet. Klassens slutsats: <em>Krasse som växer i mörker blir högre men svagare än krasse i ljus. Höjden är inte ett bra mått på hur bra en växt mår.</em> Skriv också vad du inte kan veta. Klassen testade bara krasse, så den kan inte säga att alla växter gör så.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Bra att veta</span>Ett resultat som inte stämmer med hypotesen är inte ett misslyckande. Hypotesen var att krassen blir högre i ljus. Resultatet visade något annat och klassen lärde sig något nytt. Så går forskningen framåt.</div>"], "fragor": ["Vad är skillnaden mellan slump och systematiskt fel? Ge ett exempel på vardera.", "Varför minskar slumpens betydelse när man upprepar ett försök?", "Vad menas med giltighet?", "Varför ska en slutsats också säga vad man inte vet?"]}], "begrepp": [{"term": "Felkälla", "forklaring": "Något som kan ha påverkat resultatet utan att man ville det."}, {"term": "Giltighet", "forklaring": "Om man har mätt det man ville undersöka."}, {"term": "Slump", "forklaring": "Tillfälliga variationer som inte beror på det man undersöker."}, {"term": "Slutsats", "forklaring": "Det man kan dra för svar på frågan utifrån resultatet."}, {"term": "Tillförlitlighet", "forklaring": "Hur säkra och upprepbara mätningarna är."}]}, "fordjupning": {"sektioner": [{"ikon": "✅", "titel": "Värdera resultat", "text": ["<p>Många nyheter bygger på undersökningar där forskare har jämfört grupper av människor, till exempel ”personer som äter mycket fisk lever längre”. Sådana <strong>observationsstudier</strong> är viktiga, men grupperna kan skilja sig åt på många andra sätt än det man undersöker.</p>"]}, {"ikon": "📖", "titel": "Störfaktorer", "text": ["<p>En <strong>störfaktor</strong> är något som påverkar både det man tror är orsaken och det man mäter. Kanske äter personer som äter mycket fisk också mer grönsaker, röker mindre och har högre inkomst. Då kan det vara de sakerna, och inte fisken, som gör att de lever längre.</p>", "<p>Forskare försöker räkna bort kända störfaktorer, men det kan alltid finnas sådana som ingen har tänkt på. Därför är kontrollerade experiment med slumpad fördelning det säkraste sättet att visa orsak.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade1/f_storfaktor.png\" alt=\"Bild F1.2 En störfaktor kan skapa ett samband mellan två saker som inte påverkar varandra.\"><figcaption><strong>Bild F1.2</strong> En störfaktor kan skapa ett samband mellan två saker som inte påverkar varandra.</figcaption></figure>"]}, {"ikon": "📖", "titel": "Slumpen lurar", "text": ["<p>Om du singlar slant tio gånger är det inte konstigt att få sju krona. Det betyder inte att myntet är fusk. Samma sak gäller i biologiska undersökningar: små skillnader mellan små grupper kan bero på ren slump. Ju större stickprov och ju större skillnad, desto säkrare kan man vara på att skillnaden är verklig.</p>", "<p>När du värderar ett försök, resonera om vilka felkällor som är störst, hur mycket de kan ha påverkat slutsatsen och hur du skulle förbättra försöket. Sluta med att säga hur säker slutsatsen är: ”Resultatet tyder på …, men eftersom … kan vi inte vara säkra på …”.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>”Barn som har många böcker hemma får bättre betyg.” Ge två möjliga störfaktorer.</div>"]}], "begrepp": [{"term": "Observationsstudie", "forklaring": "Man jämför grupper utan att själv ändra något."}, {"term": "Störfaktor", "forklaring": "En faktor som påverkar både den misstänkta orsaken och resultatet."}]}}, nivaStandard: "vanlig"};
innehall["biologi-m-1-1-l"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "🧪", "titel": "Labb 1.1 Reaktionstid", "text": ["<p><strong>Fråga:</strong> Hur snabb är din reaktion? Vi mäter med en fallande linjal.</p>", "<p>Ni är två och två. Ni behöver en linjal på 30 cm och en penna.</p>", "<p>Ni gör på samma sätt varje gång: samma linjal, samma hand och fem försök. Då blir testet rättvist.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade1/v_linjal.png\" alt=\"\"></figure>", "<ol><li>Din kompis håller linjalen lodrätt. Noll ska vara vid din tumme och pekfinger.</li><li>Kompisen släpper linjalen utan att säga till.</li><li>Du fångar den så fort du kan.</li><li>Läs av var du fångade linjalen. Skriv ner centimeter.</li><li>Gör fem försök. Byt sedan plats.</li></ol>"]}, {"ikon": "📖", "titel": "Räkna om till tid", "text": ["<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Fallsträcka (cm)</th><th>Reaktionstid (s)</th></tr><tr><td>5</td><td>0,10</td></tr><tr><td>10</td><td>0,14</td></tr><tr><td>15</td><td>0,17</td></tr><tr><td>20</td><td>0,20</td></tr><tr><td>25</td><td>0,23</td></tr><tr><td>30</td><td>0,25</td></tr></table></div>", "<p><strong>Säkerhet:</strong> Sitt eller stå stadigt. Skriv bara ner ditt eget värde. Du behöver inte visa det för alla.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Fallsträckan visar din reaktionstid. Gör flera försök och skriv i en tabell.</div>"]}, {"ikon": "✏️", "titel": "Öva", "text": ["<ol class=\"ovning\"><li><strong>Fyll i.</strong> Skriv rätt ord på linjen.<div class=\"alt\">Ord att välja: cm · fem · tabell</div><p>Jag gör ________ försök.</p><p>Jag skriver värdena i en ________.</p><p>Jag mäter fallsträckan i ________.</p></li><li><strong>Rita och skriv.</strong> Rita ett stapeldiagram över dina fem försök. Skriv rubrik och namn på axlarna.</li><li><strong>Skriv.</strong> Vad blev din slutsats? Svara på frågan: Hur snabb är din reaktion?</li><li><strong>Skriv.</strong> Nämn en felkälla. Vad kunde ha blivit fel?</li></ol>"]}]}, "vanlig": {"sektioner": [{"ikon": "🧪", "titel": "Labb", "text": ["<p>Du ska planera och genomföra en hel undersökning på 45 minuter. Hur snabbt reagerar du? Med en linjal som någon släpper kan du mäta det: ju kortare linjalen hinner falla innan du fångar den, desto snabbare är din reaktion.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade1/v_linjal.png\" alt=\"Bild 1.5 Linjalen släpps utan förvarning. Du fångar den med tumme och pekfinger. Läs av vid fingrarna.\"><figcaption><strong>Bild 1.5</strong> Linjalen släpps utan förvarning. Du fångar den med tumme och pekfinger. Läs av vid fingrarna.</figcaption></figure>", "<p><strong>Frågeställning:</strong> Reagerar jag snabbare med en hand än med den andra? (Eller välj en egen fråga.)</p>", "<p><strong>Hypotes:</strong> Skriv vad du tror och motivera.</p>", "<p><strong>Material:</strong> linjal 30 cm, penna, papper.</p>"]}, {"ikon": "📖", "titel": "Gör så här", "text": ["<ol><li>Bestäm oberoende variabel (vilken hand), beroende variabel (fallsträckan i cm) och vad som ska hållas lika.</li><li>Din kompis håller linjalen lodrätt med noll vid dina fingrar. Släpp utan förvarning.</li><li>Läs av var du fångade linjalen. Gör minst fem försök med varje hand.</li><li>Skriv i en tabell, räkna medelvärde och omvandla till tid med tabellen intill.</li><li>Rita ett stapeldiagram. Skriv slutsats och felkällor.</li></ol>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Fallsträcka</th><th>Reaktionstid</th></tr><tr><td>5 cm</td><td>0,10 s</td></tr><tr><td>10 cm</td><td>0,14 s</td></tr><tr><td>15 cm</td><td>0,17 s</td></tr><tr><td>20 cm</td><td>0,20 s</td></tr><tr><td>25 cm</td><td>0,23 s</td></tr><tr><td>30 cm</td><td>0,25 s</td></tr></table></div>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Utvärdera</span>Kan resultatet bero på övning och inte på handen? Hur kan du förbättra försöket?</div>", "<p class=\"not\">Säkerhet: låg risk. Sitt eller stå stadigt. Redovisa klassens värden, inte personliga.</p>"]}], "begrepp": [{"term": "Beroende", "forklaring": "Fallsträckan."}, {"term": "Lika", "forklaring": "Linjal, startläge, förvarning, antal försök."}, {"term": "Oberoende", "forklaring": "Vilken hand."}]}}, nivaStandard: "vanlig"};
innehall["biologi-m-1-2-1"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "✏️", "titel": "Vad kan vetenskap pröva?", "text": ["<p>Ett <strong>påstående</strong> är något man säger är sant.</p>", "<p>Vetenskap kan pröva ett påstående om det går att mäta eller titta. Det man mäter eller ser kallas <strong>belägg</strong>.</p>", "<p>En <strong>åsikt</strong> är vad någon tycker. Åsikter går inte att mäta. Därför kan vetenskapen inte pröva dem.</p>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Påstående</th><th>Går det att pröva?</th></tr><tr><td>Vatten fryser vid 0 °C.</td><td>Ja. Man kan mäta temperaturen.</td></tr><tr><td>Hundar har bättre luktsinne än människor.</td><td>Ja. Man kan testa det.</td></tr><tr><td>Katter är gulligare än hundar.</td><td>Nej. Det är en åsikt.</td></tr><tr><td>Ditt stjärntecken bestämmer hur du är.</td><td>Ja. Det är prövat. Det finns inga belägg.</td></tr></table></div>"]}, {"ikon": "🌱", "titel": "Pseudovetenskap", "text": ["<p>Ibland låter något som vetenskap, men det finns inga belägg. Det kallas <strong>pseudovetenskap</strong>.</p>", "<p>Horoskopet säger att ditt stjärntecken styr hur du är. Forskare har testat det. De har inte hittat belägg.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Vetenskap prövar påståenden med belägg. Åsikter går inte att pröva.</div>"]}, {"ikon": "✏️", "titel": "Öva", "text": ["<ol class=\"ovning\"><li><strong>Kryssa.</strong> Vilka påståenden går att pröva? Kryssa i rätt rutor.<div class=\"alt\"><span>Kaniner springer fortare än sköldpaddor.</span> &nbsp;·&nbsp; <span>Pizza är godast.</span> &nbsp;·&nbsp; <span>Rött är den finaste färgen.</span> &nbsp;·&nbsp; <span>Vatten kokar vid 100 °C.</span></div></li><li><strong>Ringa in.</strong> Vad är belägg?<div class=\"alt\"><span>Mätningar och observationer</span> &nbsp;·&nbsp; <span>Vad någon tycker</span> &nbsp;·&nbsp; <span>En gissning utan test</span></div></li><li><strong>Fyll i.</strong> Skriv rätt ord på linjen.<div class=\"alt\">Ord att välja: belägg · åsikt · pseudovetenskap</div><p>Mätningar som visar något kallas ________.</p><p>Det man tycker kallas en ________.</p><p>Det som låter som vetenskap men saknar belägg kallas ________.</p></li><li><strong>Skriv.</strong> Hur kan man pröva påståendet: Hundar har bättre luktsinne än människor?</li></ol>"]}]}, "vanlig": {"sektioner": [{"ikon": "🧩", "titel": "Modeller", "text": ["<p>Ett <strong>påstående</strong> är något man säger är sant. Naturvetenskapen kan pröva ett påstående om det går att undersöka med mätningar eller observationer. Det man mäter eller ser kallas <strong>belägg</strong>. Vi skiljer mellan tre saker:</p>", "<div class=\"kort-rad\"><div class=\"kort\"><strong>Belägg</strong>Mätningar och observationer som andra kan kontrollera. Exempel: vatten fryser vid 0 °C.</div><div class=\"kort\"><strong>Åsikt</strong>Vad någon tycker. Går inte att mäta. Exempel: pizza är godast.</div><div class=\"kort\"><strong>Tro</strong>Något man är övertygad om utan att det kan prövas. Vetenskapen kan varken bevisa eller motbevisa det.</div></div>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Påstående</th><th>Går det att pröva?</th><th>Hur?</th></tr><tr><td>Hundar har bättre luktsinne än människor.</td><td>Ja</td><td>Man kan testa hur svaga lukter olika djur hittar.</td></tr><tr><td>Katter är gulligare än hundar.</td><td>Nej</td><td>Det är en åsikt. Det finns inget att mäta.</td></tr><tr><td>Krasse gror snabbare vid 20 °C än vid 10 °C.</td><td>Ja</td><td>Mät hur många frön som gror vid olika temperaturer.</td></tr><tr><td>Det är fel att jaga varg.</td><td>Nej, inte bara med mätningar</td><td>Det är en värdering. Biologi kan ge fakta till diskussionen, men inte avgöra vad som är rätt.</td></tr></table></div>"]}, {"ikon": "📖", "titel": "Ett påstående måste kunna visas vara fel", "text": ["<p>Ett påstående som går att pröva måste också kunna visa sig vara fel. Om ett påstående passar med allt som kan hända kan man aldrig pröva det. ”Det kommer att hända något bra eller dåligt för dig i morgon” går aldrig att motbevisa, men säger inte heller något.</p>"]}, {"ikon": "🌱", "titel": "Pseudovetenskap", "text": ["<p>Ibland låter något vetenskapligt fast det inte är det. Det kallas <strong>pseudovetenskap</strong>: ”pseudo” betyder falsk. Det använder gärna ord som ”forskare” eller ”kliniskt bevisat”, men påståendena har inte prövats ordentligt, eller har prövats och visat sig vara fel.</p>", "<p>Horoskop är ett exempel. År 1985 fick 28 erfarna astrologer i ett dubbelblint test para ihop födelsehoroskop med personlighetsprofiler. De lyckades inte bättre än slumpen (Carlson, <em>Nature</em>).</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Fundera</span>Varför är det en styrka för vetenskapen att den kan visa sig ha fel?</div>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Vetenskap</th><th>Pseudovetenskap</th></tr><tr><td>Påståenden går att pröva och kan visa sig vara fel.</td><td>Påståenden är vaga eller går inte att pröva.</td></tr><tr><td>Bygger på undersökningar med många deltagare.</td><td>Bygger på enstaka berättelser: ”Det funkade för mig!”</td></tr><tr><td>Granskas av andra experter.</td><td>Granskas inte, eller bara av den som säljer något.</td></tr><tr><td>Ändrar sig när nya belägg kommer.</td><td>Håller fast vid idén, vad undersökningarna än visar.</td></tr></table></div>"], "fragor": ["Vad är skillnaden mellan belägg och åsikt?", "Varför kan man inte pröva ”Det är fel att jaga varg” med bara mätningar?", "Ge två kännetecken på pseudovetenskap."]}], "begrepp": [{"term": "Belägg", "forklaring": "Mätningar och observationer som visar något."}, {"term": "Pseudovetenskap", "forklaring": "Låter som vetenskap men saknar prövade belägg."}, {"term": "Påstående", "forklaring": "Något man säger är sant."}, {"term": "Åsikt", "forklaring": "Vad någon tycker. Går inte att pröva med mätningar."}]}, "fordjupning": {"sektioner": [{"ikon": "🧩", "titel": "Modeller", "text": ["<p>Naturvetenskapen är kraftfull, men den svarar bara på vissa sorters frågor: frågor som går att pröva med belägg. Frågan ”Hur påverkar en gödning tomatplantors skörd?” är en sådan. ”Är det rätt att äta kött?” är en annan sorts fråga. Biologin kan ge fakta om hur djur påverkas och hur klimatet påverkas, men vad som är rätt beror också på värderingar. Därför behövs både fakta och etiska argument.</p>"]}, {"ikon": "📖", "titel": "Ett påstående måste kunna visas vara fel", "text": ["<p>Ett vetenskapligt påstående måste kunna visa sig vara fel. Om alla tänkbara resultat passar med påståendet kan man aldrig pröva det. ”Hälsokosten hjälper om du tror på den, och om den inte hjälper tror du inte tillräckligt” går aldrig att motbevisa. Då har påståendet lämnat vetenskapen.</p>", "<p>Det betyder inte att alla icke-vetenskapliga svar är värdelösa. Konst, etik, religion och filosofi svarar på andra frågor än naturvetenskapen. Problemet uppstår när något gör anspråk på att vara vetenskap utan att kunna prövas.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Resonera</span>Vilka frågor om samma sak, till exempel jakt på varg, kan naturvetenskapen svara på, och vilka kan den inte avgöra?</div>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Påstående</th><th>Går det att pröva?</th><th>Hur skulle du pröva det?</th></tr><tr><td>Vi sover bättre i ett kallt rum.</td><td>Ja</td><td>Mät sömnlängd eller antal uppvaknanden vid olika temperaturer.</td></tr><tr><td>Naturen mår bäst när människan inte rör den.</td><td>Delvis</td><td>Måste först definiera ”mår bäst” (t.ex. antal arter) och därefter mäta. Värderingen ligger i orden.</td></tr><tr><td>Stjärntecknet styr din personlighet.</td><td>Ja, och prövat</td><td>Dubbelblint test (Carlson, Nature 1985): astrologerna klarade inte mer än slumpen.</td></tr></table></div>"]}]}}, nivaStandard: "vanlig"};
innehall["biologi-m-1-2-2"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📖", "titel": "När forskare ändrat sig", "text": ["<p>Forskare förklarar hur saker fungerar. En förklaring kallas en <strong>modell</strong>.</p>", "<p>Om nya undersökningar visar något annat, ändrar forskarna modellen. Här är tre exempel.</p>"]}, {"ikon": "🔭", "titel": "Pasteur och kolven (1861)", "text": ["<p>Förr trodde många att <strong>mikroorganismer</strong>, alltså mycket små organismer, kunde uppstå av sig själva i mat.</p>", "<p>Pasteur kokade buljong i en kolv med lång böjd hals. Damm fastnade i böjen. Buljongen förblev klar.</p>", "<p>Slutsats: små organismer kommer utifrån. De uppstår inte av sig själva.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade1/v_pasteur.png\" alt=\"\"></figure>"]}, {"ikon": "🔭", "titel": "Semmelweis och händerna (1847)", "text": ["<p>I Wien dog många mammor efter förlossningen i barnsängsfeber. Det dog fler på läkarklinikens avdelning än på barnmorskornas.</p>", "<p>Läkarna hade rört vid döda kroppar. Semmelweis trodde att något följde med händerna. Från 1847 skulle alla tvätta händerna i klorkalklösning.</p>", "<p>Dödligheten sjönk från 11,4 % till 1,3 %. Men många läkare trodde inte på honom.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade1/f_semmelweis2.png\" alt=\"\"></figure>"]}, {"ikon": "🔭", "titel": "Marshall, Warren och magsåren (1982)", "text": ["<p>Förr trodde man att magsår kom av stress och livsstil.</p>", "<p>Marshall och Warren hittade en bakterie i magsäcken, <em>Helicobacter pylori</em>. Många trodde inte på dem.</p>", "<p>År 1984 drack Marshall själv bakterier och fick en inflammation i magsäcken. Gör aldrig så själv! Idag botas magsår med antibiotika och medicin som minskar syran. De fick Nobelpriset 2005.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade1/f_hpylori.png\" alt=\"\"></figure>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>En modell kan ändras när nya undersökningar visar något annat.</div>"]}, {"ikon": "✏️", "titel": "Öva", "text": ["<ol class=\"ovning\"><li><strong>Dra streck.</strong> Vem upptäckte vad? Dra streck.<div class=\"alt\"><span>Marshall och Warren</span> &nbsp;·&nbsp; <span>Pasteur</span> &nbsp;·&nbsp; <span>Semmelweis</span> &nbsp;·&nbsp; <span>handtvätt minskar dödsfall</span> &nbsp;·&nbsp; <span>magsår kommer av en bakterie</span> &nbsp;·&nbsp; <span>små organismer kommer utifrån</span></div></li><li><strong>Ringa in.</strong> Vad hände med dödligheten efter handtvätten?<div class=\"alt\"><span>Den sjönk</span> &nbsp;·&nbsp; <span>Den steg</span> &nbsp;·&nbsp; <span>Den blev lika</span></div></li><li><strong>Fyll i.</strong> Skriv rätt ord på linjen.<div class=\"alt\">Ord att välja: modell · belägg · bakterie</div><p>En förklaring kallas en ________.</p><p>Marshall och Warren hittade en ________ i magsäcken.</p><p>Forskare ändrar sig när de får nya ________.</p></li><li><strong>Skriv.</strong> Varför ändrade forskarna sig i de tre exemplen?</li></ol>"]}]}, "vanlig": {"sektioner": [{"ikon": "📖", "titel": "Källor", "text": ["<p>En <strong>förklaringsmodell</strong> är ett sätt att förklara hur något fungerar. En modell är en förenkling av verkligheten. Den är användbar så länge den hjälper oss att förstå och förutsäga, men den kan behöva ändras när nya undersökningar visar något annat. Här är tre exempel.</p>"]}, {"ikon": "🔭", "titel": "Pasteur och svanhalskolven (1861)", "text": ["<p>Förr trodde många att <strong>mikroorganismer</strong> kunde uppstå av sig själva i mat som stod framme. Louis Pasteur kokade buljong i två sorters glaskolvar. Kolv A hade ett rakt rör, så att damm och mikroorganismer från luften kunde falla ner. Där blev buljongen grumlig. Kolv B hade en lång, böjd ”svanhals”. Luft kom in, men dammet fastnade i böjen och buljongen förblev klar.</p>", "<p>Pasteur visade att mikroorganismerna kom utifrån och inte uppstod av sig själva. Hans försök var ett bra belägg eftersom bara en sak skilde kolvarna åt: halsens form.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade1/v_pasteur.png\" alt=\"Bild 1.6 Pasteurs svanhalskolvar.\"><figcaption><strong>Bild 1.6</strong> Pasteurs svanhalskolvar.</figcaption></figure>"]}, {"ikon": "🔭", "titel": "Semmelweis och de otvättade händerna (1847)", "text": ["<p>På Allmänna sjukhuset i Wien fanns på 1840-talet två förlossningsavdelningar. På den ena arbetade läkare och läkarstudenter, som också obducerade döda kroppar. På den andra arbetade barnmorskor, som inte gjorde det. På läkarnas avdelning dog fler mödrar i barnsängsfeber. År 1846 var dödligheten där drygt fyra gånger högre (11,4 % mot 2,8 %).</p>", "<p>År 1847 dog Semmelweis vän Jakob Kolletschka efter att ha skurit sig med en obduktionskniv. Han fick samma symtom som de sjuka mödrarna. Semmelweis drog slutsatsen att ”likpartiklar” fördes över med läkarnas händer. Han krävde att alla skulle tvätta händerna i klorkalklösning. Dödligheten på läkarkliniken sjönk från 11,4 % år 1846 till 1,3 % år 1848.</p>", "<p>Ändå godtogs inte hans idé. Han kunde inte förklara <em>varför</em> det hjälpte, eftersom man ännu inte visste att bakterier kan orsaka sjukdomar, och han publicerade sig sent. Först årtionden senare fick bakterieläran fäste genom Pasteur, Lister och Koch.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade1/f_semmelweis2.png\" alt=\"Bild 1.7 Dödlighet på läkarkliniken före och efter handtvätt.\"><figcaption><strong>Bild 1.7</strong> Dödlighet på läkarkliniken före och efter handtvätt.</figcaption></figure>"]}, {"ikon": "🔭", "titel": "Marshall, Warren och magsåren (1982)", "text": ["<p>Under större delen av 1900-talet trodde man att magsår kom av stress och livsstil. Man behandlade med syrahämmande medicin, men såren kom ofta tillbaka. Man ansåg dessutom att bakterier inte kunde leva i magsäckens syra.</p>", "<p>År 1982 upptäckte de australiska forskarna Barry Marshall och Robin Warren bakterien <em>Helicobacter pylori</em> i magsäcken. De föreslog att den orsakade sårbildningen. Många trodde inte på dem. År 1984 drack Marshall själv en bakterieodling och fick en inflammation i magsäcken (gastrit). Senare visades att magsår botas när bakterien utrotas med antibiotika och syrahämmande medel. År 2005 fick de Nobelpriset i fysiologi eller medicin.</p>", "<p class=\"not\">Marshalls självförsök var riskabelt. Forskning på människor måste idag etikprövas.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade1/f_hpylori.png\" alt=\"Bild 1.8 Helicobacter pylori i magsäcken.\"><figcaption><strong>Bild 1.8</strong> <em>Helicobacter pylori</em> i magsäcken.</figcaption></figure>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Gemensamt för exemplen</span>I alla tre fallen fanns ett belägg från en undersökning som inte passade den gamla förklaringen. Men det tog tid att övertyga andra. Forskarvärlden vill ha belägg som kan granskas och upprepas, och helst en modell som förklarar <em>hur</em> det fungerar.</div>"], "fragor": ["Vad visade Pasteurs svanhalskolv?", "Vad var beläggen för Semmelweis idé?", "Varför trodde många inte på honom?", "Vad menas med att en modell är en förenkling? Ge ett exempel."]}]}, "fordjupning": {"sektioner": [{"ikon": "📖", "titel": "Källor", "text": ["<p>I grundtexten mötte du Pasteur, Semmelweis samt Marshall och Warren. Nu ska vi jämföra dem och fråga varför det ibland tar så lång tid att ändra en förklaring.</p>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th></th><th>Pasteur (1861)</th><th>Semmelweis (1847)</th><th>Marshall och Warren (1982)</th></tr><tr><td>Gammal förklaring</td><td>Små organismer kan uppstå av sig själva.</td><td>Barnsängsfeber har många orsaker, ingen tänker på händerna.</td><td>Magsår beror på stress och livsstil. Bakterier kan inte leva i magsyran.</td></tr><tr><td>Belägg</td><td>Buljong i svanhalskolv förblev klar, i rak kolv blev den grumlig.</td><td>Dödligheten på läkarkliniken föll från 11,4 % till 1,3 % efter handtvätt.</td><td>Bakterie i magsäcken. Marshalls självförsök 1984. Antibiotika botar.</td></tr><tr><td>Motstånd</td><td>Fick mothugg men kontrollerade försök övertygade.</td><td>Hånades. Saknade förklaring till hur. Fick inte förlängt kontrakt.</td><td>Marshall möttes av stark skepsis.</td></tr><tr><td>Vad övertygade?</td><td>Ett enkelt och upprepbart försök.</td><td>Bakterieläran växte fram årtionden senare.</td><td>Upprepade studier och en behandling som fungerade. Nobelpriset 2005.</td></tr></table></div>"]}, {"ikon": "📖", "titel": "Mönstret", "text": ["<p>I alla tre fall passade resultatet inte den förklaring som alla trodde på. Det är inte konstigt att forskare håller fast vid en modell som fungerat länge. En modell är en förenkling som har varit användbar, och en enstaka avvikelse kan bero på ett fel. Motståndet kan därför vara rimligt i början. Men när belägg samlas, från olika forskare och olika metoder, ändras bilden.</p>", "<p>Det betyder inte att alla nya idéer har rätt. Marshall och Warren fick rätt för att de hade belägg som kunde granskas och upprepas, inte för att de var envisa.</p>"]}, {"ikon": "🧩", "titel": "Modeller har begränsningar", "text": ["<p>Ett exempel: bakterien <em>Helicobacter pylori</em> orsakar magsår, men långt ifrån alla som är smittade får magsår. Modellen ”bakterie orsakar magsår” är användbar, men inte hela förklaringen. Fler faktorer spelar in.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Lärdom</span>En bra modell förklarar vad man ser, förutsäger nya saker och kan prövas. Den behöver inte vara hela sanningen för att vara användbar.</div>", "<div class=\"ruta ruta-varning\"><span class=\"ruta-rubrik\">Etik</span>Marshalls självförsök var riskabelt. Forskning på människor måste granskas av en etikprövningsmyndighet.</div>"]}]}}, nivaStandard: "vanlig"};
innehall["biologi-m-1-2-3"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "🔎", "titel": "Söka information och bedöma källor", "text": ["<p>När du söker på nätet: använd flera sökord. Till exempel <em>sömn tonåringar forskning</em>.</p>", "<p>En <strong>källa</strong> är där informationen kommer ifrån. <strong>Avsändaren</strong> är den som har skrivit eller gjort texten. Fråga dig:</p>", "<p><strong>Trovärdig</strong> betyder att man kan lita på den. <strong>Relevant</strong> betyder att den passar din fråga.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade1/l_fyra.png\" alt=\"\"></figure>", "<p>Fråga också: Finns det <strong>belägg</strong>? Reklam har ofta inga belägg. Den vill sälja.</p>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Fråga om källan</th><th>Bra tecken</th></tr><tr><td>Vem har skrivit?</td><td>Forskare, myndighet eller en känd organisation</td></tr><tr><td>Varför är det skrivet?</td><td>Att informera. Inte att sälja</td></tr><tr><td>Finns det belägg?</td><td>Mätningar, undersökningar eller länkar till forskning</td></tr><tr><td>Är det nytt?</td><td>Skrivet för inte så länge sedan</td></tr><tr><td>Säger andra källor samma sak?</td><td>Ja, minst två till</td></tr></table></div>", "<div class=\"ruta ruta-fakta\"><span class=\"ruta-rubrik\">Så argumenterar du</span>strong></strong>1. <strong>Påstående:</strong> Jag tycker att …<br>2. <strong>Belägg:</strong> Jag tycker det eftersom …<br>3. <strong>Motargument:</strong> Någon kan säga att … Men …<br>4. <strong>Slutsats:</strong> Alltså …</div>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Fråga: vem, varför, belägg, när och fler källor. Då ser du om en källa går att lita på.</div>"]}, {"ikon": "✏️", "titel": "Öva", "text": ["<ol class=\"ovning\"><li><strong>Dra streck.</strong> Vilken fråga passar? Dra streck.<div class=\"alt\"><span>Fler källor?</span> &nbsp;·&nbsp; <span>När?</span> &nbsp;·&nbsp; <span>Står det på fler ställen?</span> &nbsp;·&nbsp; <span>Varför?</span> &nbsp;·&nbsp; <span>Vem har skrivit texten?</span> &nbsp;·&nbsp; <span>Vem?</span> &nbsp;·&nbsp; <span>Vill de sälja något?</span> &nbsp;·&nbsp; <span>Är texten gammal?</span></div></li><li><strong>Ringa in.</strong> Reklamen säger: ”Superbär botar ALLT på en dag!” Vad tror du?<div class=\"alt\"><span>Det är sant</span> &nbsp;·&nbsp; <span>Det är nog inte sant</span></div></li><li><strong>Fyll i.</strong> Skriv rätt ord på linjen.<div class=\"alt\">Ord att välja: trovärdig · relevant · belägg</div><p>En källa som går att lita på är ________.</p><p>En källa som passar min fråga är ________.</p><p>Mätningar som visar något kallas ________.</p></li><li><strong>Skriv.</strong> Hur kan du se om en webbsida går att lita på?</li></ol>"]}]}, "vanlig": {"sektioner": [{"ikon": "💬", "titel": "Argument", "text": ["<p>Varje dag möter du påståenden om hälsa, mat, djur och miljö: i sociala medier, reklam, nyheter och samtal. Att söka bra information börjar med att använda flera sökord, till exempel <em>sömn tonåringar forskning</em>, och att jämföra flera källor. Sedan måste du bedöma källorna.</p>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Typ av källa</th><th>Exempel</th><th>Styrka</th><th>Se upp med</th></tr><tr><td>Myndighet</td><td>Folkhälsomyndigheten, Naturvårdsverket, 1177</td><td>Faktagranskad, oberoende</td><td>Kan vara allmänt hållen</td></tr><tr><td>Forskning</td><td>Universitet, vetenskaplig artikel</td><td>Granskad av andra experter</td><td>En enda studie räcker inte. Kan vara svår att läsa</td></tr><tr><td>Nyhetsmedia</td><td>Tidningar, tv</td><td>Snabb och lättläst</td><td>Rubriker kan vara vinklade</td></tr><tr><td>Sociala medier</td><td>Inlägg, videor</td><td>Kan peka ut nya idéer</td><td>Ofta ogranskat. Berättelser är inte belägg</td></tr><tr><td>Reklam och företag</td><td>Webbplats för en produkt</td><td>Känner sin produkt</td><td>Vill sälja. Tendens</td></tr></table></div>"]}, {"ikon": "📖", "titel": "Trovärdig och relevant", "text": ["<p>En källa är <strong>trovärdig</strong> om man kan lita på den. En källa är <strong>relevant</strong> om den passar din fråga. En trovärdig källa kan vara irrelevant: en studie om möss säger inte nödvändigtvis något om människor. Fyra frågor brukar kallas de källkritiska kriterierna:</p>", "<div class=\"kort-rad\"><div class=\"kort\"><strong>Äkthet</strong>Är källan den den utger sig för att vara? Är bilden eller citatet äkta?</div><div class=\"kort\"><strong>Tid</strong>När skrevs det? Är informationen fortfarande aktuell?</div><div class=\"kort\"><strong>Beroende</strong>Var kommer uppgifterna ifrån? Har avsändaren själv undersökt, eller bara hört från någon annan?</div><div class=\"kort\"><strong>Tendens</strong>Vill avsändaren något: sälja, övertyga eller påverka? Visas flera sidor?</div></div>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade1/v_inlagg.png\" alt=\"Bild 1.9 Ett påhittat inlägg i sociala medier, granskat med de källkritiska kriterierna.\"><figcaption><strong>Bild 1.9</strong> Ett påhittat inlägg i sociala medier, granskat med de källkritiska kriterierna.</figcaption></figure>"]}, {"ikon": "💬", "titel": "Argumentera", "text": ["<p>När du har granskat källorna ska du kunna använda dem. Ett bra argument har ett <strong>påstående</strong>, ett <strong>belägg</strong> och ett svar på ett <strong>motargument</strong>.</p>", "<p><strong>Exempel:</strong> <em>Skolor bör ha rutiner för handtvätt före lunch. Handtvätt minskar spridning av infektioner, vilket Semmelweis exempel visar. Någon kan säga att det tar tid. Men tiden är liten jämfört med de dagar elever är sjuka.</em></p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Så argumenterar du</span>1. Påstående<br>2. Belägg (varför?)<br>3. Motargument (vad kan någon säga emot?)<br>4. Bemöt det<br>5. Slutsats</div>"], "fragor": ["Vad är skillnaden mellan trovärdig och relevant?", "Varför är reklam en källa man ska vara försiktig med?", "Granska ett påstående med hjälp av de fyra kriterierna.", "Skriv ett kort argument om ett eget påstående, med belägg och motargument."]}]}, "fordjupning": {"sektioner": [{"ikon": "💬", "titel": "Argument", "text": ["<p>Ibland säger trovärdiga källor emot varandra. Då räcker det inte att fråga om en källa är trovärdig. Man måste väga dem mot varandra: Vilken bygger på flest och bäst undersökningar? Vem har gjort studien, och vem har betalat för den? Finns det en oberoende upprepning?</p>", "<div class=\"kort-rad\"><div class=\"kort\"><strong>Oberoende</strong>Har källan undersökt själv eller bara hört av andra? Går uppgifterna att följa tillbaka?</div><div class=\"kort\"><strong>Tendens</strong>Vem tjänar på budskapet? Vem betalade för undersökningen?</div><div class=\"kort\"><strong>Samsyn</strong>Säger andra, oberoende källor samma sak? Vad säger sammanställningar?</div><div class=\"kort\"><strong>Aktualitet</strong>Är det nytt nog? Har nyare studier ändrat bilden?</div></div>"]}, {"ikon": "📊", "titel": "Läs diagram och statistik med kritiskt öga", "text": ["<p><strong>Korrelation är inte orsak.</strong> När glassförsäljningen ökar, ökar också antalet drunkningsolyckor. Båda beror på en tredje sak: värmen.</p>", "<p><strong>Avkortad axel.</strong> Om y-axeln börjar på 90 i stället för 0 ser en liten skillnad enorm ut.</p>", "<p><strong>Relativ ökning.</strong> ”Risken dubblas!” kan betyda att den går från 1 på 100 000 till 2 på 100 000. Fråga alltid efter hur stor risken var från början.</p>", "<p><strong>Sponsring och tendens.</strong> En studie betald av ett företag är inte automatiskt fel, men man bör se om den är oberoende granskad och om andra har fått samma resultat.</p>", "<figure class=\"sek-bild\"><img src=\"bilder/biologi-omrade1/v_glass.png\" alt=\"Bild F1.3 Två kurvor som följer varandra utan att den ena orsakar den andra.\"><figcaption><strong>Bild F1.3</strong> Två kurvor som följer varandra utan att den ena orsakar den andra.</figcaption></figure>"]}, {"ikon": "💬", "titel": "Bemöt motargument", "text": ["<p>Ett starkt argument tar motargumentet på allvar. Skriv påstående, belägg, det starkaste motargumentet och ett svar som visar varför beläggen ändå väger tyngre, eller var du kan hålla med. Avsluta med en slutsats som säger hur säker du är.</p>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Tänk efter</span>En tidning skriver: ”Studie: Kaffe förlänger livet!” Vilka tre frågor ställer du innan du tror på det?</div>"]}]}}, nivaStandard: "vanlig"};
innehall["biologi-m-1-2-l"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "🧪", "titel": "Labb 1.2 Granska ett påstående", "text": ["<p><strong>Fråga:</strong> Är påståendet sant? Du ska granska det med hjälp av två källor.</p>", "<p>Välj ett påstående:</p>", "<ol><li>Tio procent av hjärnan används.</li><li>Socker gör barn hyperaktiva.</li><li>Blixten slår aldrig ned två gånger på samma plats.</li></ol>", "<ol><li>Sök efter påståendet. Hitta två olika källor.</li><li>Fyll i checklistan för varje källa.</li><li>Bestäm: Är påståendet sant, osant eller osäkert?</li><li>Skriv ett kort argument. Använd mallen.</li></ol>", "<div class=\"ruta ruta-fakta\"><span class=\"ruta-rubrik\">Så argumenterar du</span>strong></strong>1. <strong>Påstående:</strong> Jag tycker att …<br>2. <strong>Belägg:</strong> Jag tycker det eftersom …<br>3. <strong>Motargument:</strong> Någon kan säga att … Men …<br>4. <strong>Slutsats:</strong> Alltså …</div>", "<p><strong>Säkerhet:</strong> Skriv inga personuppgifter. Klicka inte på reklam eller länkar du inte litar på.</p>", "<div class=\"ruta ruta-visste\"><span class=\"ruta-rubrik\">Kom ihåg</span>Granska varje källa. Svara sedan med påstående, belägg, motargument och slutsats.</div>"]}, {"ikon": "✏️", "titel": "Öva", "text": ["<ol class=\"ovning\"><li><strong>Skriv.</strong> Källa 1: Skriv webbadress eller namn. Svara sedan: vem har skrivit? Är den trovärdig?</li><li><strong>Skriv.</strong> Källa 2: Skriv webbadress eller namn. Svara sedan: vem har skrivit? Är den trovärdig?</li><li><strong>Skriv.</strong> Skriv ditt argument.</li></ol>"]}]}, "vanlig": {"sektioner": [{"ikon": "🧪", "titel": "Labb", "text": ["<p>Du ska granska ett påstående med hjälp av två källor och skriva ett argument med belägg och motargument. Arbetet tar 45 minuter. Välj ett påstående:</p>", "<ul><li>Vi använder bara tio procent av hjärnan.</li><li>Socker gör barn hyperaktiva.</li><li>Blixten slår aldrig ned två gånger på samma plats.</li></ul>"]}, {"ikon": "📖", "titel": "Gör så här", "text": ["<ol><li>Sök efter påståendet med flera sökord. Hitta två källor av olika typ, till exempel en myndighet och en tidning.</li><li>Bedöm varje källa: äkthet, tid, beroende och tendens. Är den trovärdig? Är den relevant?</li><li>Bestäm om påståendet är sant, osant eller osäkert, och skriv varför.</li><li>Skriv ett argument: påstående, belägg, motargument, bemötande, slutsats.</li></ol>", "<div class=\"tabell-ram\"><table class=\"tabell\"><tr><th>Fråga</th><th>Källa 1</th><th>Källa 2</th></tr><tr><td>Vem har skrivit?</td><td></td><td></td></tr><tr><td>Varför?</td><td></td><td></td></tr><tr><td>Belägg?</td><td></td><td></td></tr><tr><td>Hur nytt?</td><td></td><td></td></tr><tr><td>Trovärdig?</td><td></td><td></td></tr></table></div>", "<div class=\"ruta ruta-tank\"><span class=\"ruta-rubrik\">Utvärdera</span>Vilken källa litar du mest på? Varför? Hur kan två trovärdiga källor säga olika?</div>", "<p class=\"not\">Säkerhet: skriv inga personuppgifter och klicka inte på reklam eller länkar du inte litar på.</p>"]}]}}, nivaStandard: "vanlig"};
innehall["biologi-m-1-s"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "📌", "titel": "Sammanfattning", "text": ["<p>Läs orden och titta på bilderna. Du kan komma tillbaka hit när du läser.</p>", "<p>Här är allt det viktigaste i kapitlet. Läs det en gång till.</p>", "<ul class=\"viktigast\"><li>Biologi är läran om allt som lever.</li></ul>", "<ul class=\"viktigast\"><li>Forskare frågar, gissar (hypotes), testar och svarar (slutsats).</li></ul>", "<ul class=\"viktigast\"><li>I ett rättvist test ändrar man bara en sak.</li></ul>", "<ul class=\"viktigast\"><li>Resultatet är det man mäter. Slutsatsen är det man lär sig.</li></ul>", "<ul class=\"viktigast\"><li>Resultatet kan bli fel. Gör om testet och skriv vad som kan ha blivit fel.</li></ul>", "<ul class=\"viktigast\"><li>Vetenskap prövar påståenden med belägg. Åsikter går inte att pröva.</li></ul>", "<ul class=\"viktigast\"><li>En modell kan ändras när nya undersökningar visar något annat.</li></ul>", "<ul class=\"viktigast\"><li>Tro inte på allt du läser. Kolla vem, varför, belägg, när och fler källor.</li></ul>"]}], "begrepp": [{"term": "avsändare", "forklaring": "den som har skrivit eller gjort texten"}, {"term": "belägg", "forklaring": "mätningar eller observationer som visar något"}, {"term": "biologi", "forklaring": "läran om allt som lever"}, {"term": "diagram", "forklaring": "en bild av siffror, till exempel staplar"}, {"term": "felkälla", "forklaring": "något som kan göra att resultatet blir fel"}, {"term": "hypotes", "forklaring": "det man tror blir svaret, och varför"}, {"term": "källa", "forklaring": "där informationen kommer ifrån"}, {"term": "mikroorganism", "forklaring": "en mycket liten organism, till exempel en bakterie"}, {"term": "modell", "forklaring": "ett sätt att förklara hur något fungerar"}, {"term": "organism", "forklaring": "allt som lever, till exempel djur, växter och bakterier"}, {"term": "pseudovetenskap", "forklaring": "låter som vetenskap men saknar belägg"}, {"term": "påstående", "forklaring": "något man säger är sant"}, {"term": "relevant", "forklaring": "passar min fråga"}, {"term": "resultat", "forklaring": "det man mäter eller ser"}, {"term": "rättvist test", "forklaring": "man ändrar bara en sak. Allt annat är lika"}, {"term": "slump", "forklaring": "något som händer av en tillfällighet"}, {"term": "slutsats", "forklaring": "det man lär sig av resultatet"}, {"term": "tabell", "forklaring": "ett sätt att skriva ner det man mäter"}, {"term": "trovärdig", "forklaring": "går att lita på"}, {"term": "undersökningsbar fråga", "forklaring": "en fråga du kan svara på genom att mäta eller titta"}, {"term": "variabel", "forklaring": "något som kan ändras eller mätas"}, {"term": "åsikt", "forklaring": "vad någon tycker. Går inte att mäta"}]}, "vanlig": {"sektioner": [{"ikon": "📌", "titel": "Sammanfattning", "text": ["<ul><li><strong>Biologi</strong> är läran om livet. Biologer arbetar i fält, i labb och vid datorer.</li><li>En <strong>undersökningsbar fråga</strong> går att besvara med mätningar. En <strong>hypotes</strong> är ett prövbart svar med motivering.</li><li>I ett rättvist försök ändrar man en <strong>oberoende variabel</strong>, mäter en <strong>beroende variabel</strong> och håller alla andra lika. En kontrollgrupp ger något att jämföra med.</li><li>Värden skrivs i tabell med rubriker och enheter. Diagram har rubrik och axlar med namn och enhet. Man räknar medelvärde av upprepningar.</li><li>Resultat kan bli fel av slump eller systematiska fel. Upprepning minskar slumpens betydelse. Slutsatsen ska svara på frågan och stämma med resultatet.</li><li>Vetenskap prövar påståenden med belägg. Åsikter och tro går inte att pröva med mätningar. Pseudovetenskap saknar prövade belägg.</li><li>Förklaringsmodeller ändras när nya belägg kommer: Pasteur, Semmelweis, Marshall och Warren.</li><li>Bedöm källor med äkthet, tid, beroende och tendens. Skilj trovärdig från relevant. Ett argument har påstående, belägg och bemötande av motargument.</li></ul>"]}], "begrepp": [{"term": "Belägg", "forklaring": "Observationer och mätningar som stöder en slutsats."}, {"term": "Beroende variabel", "forklaring": "Det man mäter i en undersökning."}, {"term": "Felkälla", "forklaring": "Något som kan ha påverkat resultatet utan att man ville det."}, {"term": "Förklaringsmodell", "forklaring": "Ett sätt att förklara hur något fungerar."}, {"term": "Giltighet", "forklaring": "Om man har mätt det man ville undersöka."}, {"term": "Hypotes", "forklaring": "Ett möjligt, prövbart svar på en fråga."}, {"term": "Kontrollerade variabler", "forklaring": "Det som hålls lika för att testet ska bli rättvist."}, {"term": "Kontrollgrupp", "forklaring": "Grupp där man inte ändrar något, att jämföra med."}, {"term": "Medelvärde", "forklaring": "Summan av värdena delat med antalet."}, {"term": "Oberoende variabel", "forklaring": "Det man själv ändrar i en undersökning."}, {"term": "Pseudovetenskap", "forklaring": "Låter vetenskapligt men saknar prövade belägg."}, {"term": "Relevant", "forklaring": "Passar min fråga."}, {"term": "Slump", "forklaring": "Tillfälliga variationer som inte beror på det man undersöker."}, {"term": "Teori", "forklaring": "En väl prövad förklaring som stöds av många belägg."}, {"term": "Tillförlitlighet", "forklaring": "Hur säkra och upprepbara mätningarna är."}, {"term": "Trovärdig", "forklaring": "Går att lita på."}, {"term": "Undersökningsbar fråga", "forklaring": "Kan besvaras med mätningar eller observationer."}]}}, nivaStandard: "vanlig"};
innehall["biologi-m-1-t"] = {nivaer: {"lattlast": {"sektioner": [{"ikon": "🤔", "titel": "Testa dig själv", "text": ["<p>Nu får du visa vad du har lärt dig. Du kan titta i kapitlet om du vill.</p>"]}, {"ikon": "✏️", "titel": "Öva", "text": ["<ol class=\"ovning\"><li><strong>Ringa in.</strong> Vem forskar om växter?<div class=\"alt\"><span>Botaniker</span> &nbsp;·&nbsp; <span>Zoolog</span> &nbsp;·&nbsp; <span>Marinbiolog</span></div></li><li><strong>Dra streck.</strong> Dra streck till rätt förklaring.<div class=\"alt\"><span>Belägg</span> &nbsp;·&nbsp; <span>Hypotes</span> &nbsp;·&nbsp; <span>Resultat</span> &nbsp;·&nbsp; <span>Slutsats</span> &nbsp;·&nbsp; <span>det man lär sig</span> &nbsp;·&nbsp; <span>det man mäter eller ser</span> &nbsp;·&nbsp; <span>det man tror blir svaret, och varför</span> &nbsp;·&nbsp; <span>mätningar som visar något</span></div></li><li><strong>Sant eller falskt.</strong> Kryssa i rätt ruta.<div class=\"alt\"><span>Sant</span> &nbsp;·&nbsp; <span>Falskt</span></div></li><li><strong>Ringa in.</strong> Vilken fråga går att undersöka?<div class=\"alt\"><span>Är hundar snälla?</span> &nbsp;·&nbsp; <span>Hur högt hoppar en groda?</span> &nbsp;·&nbsp; <span>Är sommar bäst?</span></div></li><li><strong>Skriv.</strong> Du vill testa om bönor gror bäst i varmt eller kallt. Vad ska du ändra? Vad ska vara lika?</li><li><strong>Skriv.</strong> Ali säger: ”Mina bönor i värmen grodde snabbast. Alltså gror alla bönor bäst i värme.” Vad borde Ali göra för att vara säkrare?</li><li><strong>Skriv.</strong> Semmelweis fick läkarna att tvätta händerna. Vad hände med dödligheten?</li><li><strong>Skriv.</strong> En webbsida säger att ett te botar förkylning på en timme. Hur kan du ta reda på om det stämmer?</li></ol>"]}]}, "vanlig": {"sektioner": [{"ikon": "🤔", "titel": "Testa dig själv", "text": ["<p class=\"not\">Uppgifterna liknar uppgifterna i nationella prov i biologi. Personer, annonser och mätvärden är påhittade. ● grundläggande  ●● utvecklat  ●●● välutvecklat</p>"]}, {"ikon": "📖", "titel": "Del A · Välj ett alternativ", "text": ["<p class=\"provfraga\"><strong>1</strong> Elin undersöker om temperaturen påverkar hur mycket gas jäst bildar. Hon mäter mängden gas efter 20 minuter. Vilken är den beroende variabeln? <em class=\"poang\">(●)</em></p>", "<ul class=\"alts\"><li>A Temperaturen</li><li>B Mängden gas</li><li>C Mängden jäst</li><li>D Tiden, 20 minuter</li></ul>", "<p class=\"provfraga\"><strong>2</strong> Vilket påstående går att pröva med naturvetenskapliga metoder? <em class=\"poang\">(●)</em></p>", "<ul class=\"alts\"><li>A Blåbär smakar godare än lingon.</li><li>B Krasse gror snabbare vid 20 °C än vid 10 °C.</li><li>C Det är fel att jaga varg.</li><li>D Naturen vill alltid vara i balans.</li></ul>", "<p class=\"provfraga\"><strong>3</strong> Vad visade att handtvätt hjälpte på Semmelweis avdelning? <em class=\"poang\">(●)</em></p>", "<ul class=\"alts\"><li>A Läkarna blev tröttare.</li><li>B Dödligheten sjönk från 11,4 % till 1,3 %.</li><li>C Barnmorskorna slutade arbeta.</li><li>D Fler kvinnor kom till sjukhuset.</li></ul>"]}, {"ikon": "📖", "titel": "Del B · Svara kort", "text": ["<p class=\"provfraga\"><strong>4</strong> Förklara varför man upprepar ett försök flera gånger och räknar ut ett medelvärde. <em class=\"poang\">(●●)</em></p>", "<p class=\"provfraga\"><strong>5</strong> Förklara skillnaden mellan en trovärdig och en relevant källa. Ge ett exempel. <em class=\"poang\">(●●)</em></p>"]}, {"ikon": "🔎", "titel": "Del C · Planera en undersökning", "text": ["<p class=\"provfraga\"><strong>6</strong> Noah vill ta reda på om gödning påverkar hur mycket ärtplantor växer. Han har ärtfrön, krukor, jord, vatten, flytande gödning och en linjal. Planera undersökningen. Skriv<br>a) en frågeställning och en hypotes,<br>b) oberoende och beroende variabel,<br>c) minst tre variabler som ska hållas lika. <em class=\"poang\">(●●●)</em></p>", "<p class=\"provfraga\"><strong>7</strong> Mira vill ta reda på om temperaturen påverkar hur snabbt bönor gror. Hon sätter bönor i en burk med fuktigt papper i ett soligt fönster och bönor i en annan burk i kylskåpet.<br>a) Ge ett skäl till att Miras undersökning inte blir rättvis.<br>b) Föreslå en förbättring. <em class=\"poang\">(●●)</em></p>"]}, {"ikon": "🔎", "titel": "Del E · Granska information", "text": ["<p class=\"provfraga\"><strong>8</strong> Läs annonsen och svara.<span class=\"pahittat\">Påhittad annons</span><strong>NYHET! DetoxPlåstret™</strong><br>Sätt plåstret under foten när du sover – på morgonen har det blivit brunt av alla gifter som dragits ut ur kroppen! ”Jag har aldrig mått så bra”, säger Anna, 34. Vetenskapligt utvecklat.a) Använd de källkritiska kriterierna. Ge två skäl till att vara skeptisk.<br>b) Hur skulle man kunna undersöka om plåstret verkligen drar ut gifter? <em class=\"poang\">(●●●)</em></p>"]}, {"ikon": "📖", "titel": "Del F · Resonera", "text": ["<p class=\"provfraga\"><strong>9</strong> Välj ett av exemplen Pasteur, Semmelweis eller Marshall och Warren. Förklara hur förklaringen ändrades när nya belägg kom, och varför det tog tid att övertyga andra. <em class=\"poang\">(●●)</em></p>"]}]}, "fordjupning": {"sektioner": [{"ikon": "🤔", "titel": "Testa dig själv", "text": ["<p class=\"not\">Uppgifterna liknar de svåraste uppgifterna på nationella prov. Personer, rubriker och mätvärden är påhittade. Svara utförligt och resonera i flera led. ● grundläggande  ●● utvecklat  ●●● välutvecklat</p>", "<p class=\"provfraga\"><strong>1</strong> Ett företag påstår att deras sportdryck ger bättre kondition. Planera en undersökning som kan pröva påståendet. Beskriv hur du använder kontrollgrupp, placebo, randomisering och blindning, och förklara varför varje del behövs. <em class=\"poang\">(●●●)</em></p>", "<p class=\"provfraga\"><strong>2</strong> Semmelweis jämförde två avdelningar. Förklara varför jämförelsen gjorde hans slutsats starkare, och ge ett skäl till att hans slutsats ändå inte var helt säker innan handtvätten infördes. <em class=\"poang\">(●●●)</em></p>", "<p class=\"provfraga\"><strong>3</strong> En tidning skriver: ”Ny studie: Kaffe gör att du lever längre! Forskare har följt 500 000 personer och de som drack 2–3 koppar om dagen dog i lägre grad.” Värdera rubriken med begreppen observationsstudie, störfaktor och orsakssamband. Vad skulle krävas för att man säkert kan säga att kaffet är orsaken? <em class=\"poang\">(●●●)</em></p>", "<p class=\"provfraga\"><strong>4</strong> Två klasser testar om gödning gör att bönplantor växer högre. Klass A har 3 plantor per grupp och får skillnaden 4 mm. Klass B har 30 plantor per grupp och får skillnaden 2 mm. Vilket resultat litar du mest på? Motivera och diskutera slumpens betydelse. <em class=\"poang\">(●●)</em></p>", "<p class=\"provfraga\"><strong>5</strong> Tabellen om jäst (F1.1.2) har ett avvikande värde vid 40 °C. Förklara hur du hanterar det och hur du redovisar resultatet så att läsaren kan avgöra hur säker slutsatsen är. <em class=\"poang\">(●●●)</em></p>", "<p class=\"provfraga\"><strong>6</strong> Jämför två av exemplen Pasteur, Semmelweis och Marshall och Warren. Vad är gemensamt, och vad skiljer dem åt? Resonera om varför nya idéer ibland möts av motstånd, och om motståndet alltid är oberättigat. <em class=\"poang\">(●●●)</em></p>", "<p class=\"provfraga\"><strong>7</strong> Två trovärdiga källor säger olika om ett kosttillskott: en myndighet avråder, en studie betald av tillverkaren visar effekt. Resonera om hur du väger källorna och vilken ytterligare information du skulle vilja ha. Formulera ett argument och bemöt ett motargument. <em class=\"poang\">(●●●)</em></p>"]}]}}, nivaStandard: "vanlig"};
